import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import Chart from "chart.js/auto";
import { companies, marketIndices, generateDemo, simulateUpdate, updateStock, MAX_HISTORY, CACHE_DURATION } from "./data";
import "./main.css";
import "./components.css";
import "./animations.css";
import "@fortawesome/fontawesome-free/css/all.min.css";

const API_KEY = process.env.REACT_APP_ALPHA_VANTAGE_API_KEY || "";
const UPDATE_INTERVAL = 3 * 60 * 1000;
const API_DELAY = 12000;

function sleep(ms) { return new Promise(resolve => setTimeout(resolve, ms)); }

function App() {
  const [stocks, setStocks] = useState(() => {
    try {
      const cached = JSON.parse(localStorage.getItem("stockData"));
      if (cached && Date.now() - cached.timestamp < CACHE_DURATION) return cached.stocks;
    } catch {}
    return generateDemo();
  });
  const [watchlist, setWatchlist] = useState(["Apple", "Microsoft", "Alphabet"]);
  const [filters, setFilters] = useState({ search: "", sector: "", cap: "" });
  const [chartType, setChartType] = useState("line");
  const [theme, setTheme] = useState(() => localStorage.getItem("theme") || "dark");
  const [marketStatus, setMarketStatus] = useState("LIVE");
  const [updating, setUpdating] = useState(false);
  const [selectedStock, setSelectedStock] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    document.body.className = theme === "light" ? "light-theme" : "dark-theme";
    const root = document.documentElement;
    if (theme === "light") {
      root.style.setProperty("--bg-primary","#ffffff");
      root.style.setProperty("--bg-secondary","#f8f9fa");
      root.style.setProperty("--bg-tertiary","#e9ecef");
      root.style.setProperty("--bg-panel","#ffffff");
      root.style.setProperty("--text-primary","#212529");
      root.style.setProperty("--text-secondary","#6c757d");
      root.style.setProperty("--border-color","#dee2e6");
    } else {
      root.style.setProperty("--bg-primary","#0a0e1a");
      root.style.setProperty("--bg-secondary","#1a1f35");
      root.style.setProperty("--bg-tertiary","#242b42");
      root.style.setProperty("--bg-panel","#1e2438");
      root.style.setProperty("--text-primary","#e6e8ef");
      root.style.setProperty("--text-secondary","#9ca3b4");
      root.style.setProperty("--border-color","#2d3748");
    }
  }, [theme]);

  const refresh = useCallback(async () => {
    if (updating) return;
    setUpdating(true); setMarketStatus("UPDATING");
    try {
      let next = stocks;
      for (const [name, company] of Object.entries(companies)) {
        let result = null;
        if (API_KEY) {
          try {
            const response = await fetch(`https://www.alphavantage.co/query?function=GLOBAL_QUOTE&symbol=${company.symbol}&apikey=${API_KEY}`);
            const data = await response.json();
            const q = data["Global Quote"];
            if (q && q["05. price"]) {
              result = {
                price: parseFloat(q["05. price"]),
                change: parseFloat(q["09. change"]),
                changePercent: q["10. change percent"],
                volume: parseInt(q["06. volume"], 10) || 0,
                lastUpdated: new Date()
              };
            }
          } catch {}
        }
        next = result ? updateStock(next, name, result) : simulateUpdate(next, name);
        if (watchlist.includes(name)) setStocks(next);
        if (name !== Object.keys(companies).at(-1)) await sleep(API_DELAY);
      }
      setStocks(next);
      localStorage.setItem("stockData", JSON.stringify({ timestamp: Date.now(), stocks: next }));
      setMarketStatus("LIVE");
    } catch (e) {
      console.error("Update failed:", e);
      setMarketStatus("ERROR");
    } finally { setUpdating(false); }
  }, [updating, stocks, watchlist]);

  useEffect(() => {
    const timer = setTimeout(() => { refresh(); setLoading(false); }, 3000);
    const interval = setInterval(() => refresh(), UPDATE_INTERVAL);
    return () => { clearTimeout(timer); clearInterval(interval); };
  }, []); // intentionally start the same background cadence as the original app

  const addToWatchlist = name => setWatchlist(prev => prev.includes(name) ? prev : [...prev, name]);
  const removeFromWatchlist = name => setWatchlist(prev => prev.filter(x => x !== name));

  const filteredStocks = useMemo(() => {
    let list = Object.entries(companies);
    const term = filters.search.toLowerCase();
    if (term) list = list.filter(([name, info]) => name.toLowerCase().includes(term) || info.symbol.toLowerCase().includes(term) || info.sector.toLowerCase().includes(term));
    if (filters.sector) list = list.filter(([,info]) => info.sector === filters.sector);
    if (filters.cap) list = list.filter(([,info]) => {
      const cap = info.marketCap;
      if (filters.cap === "large") return cap.includes("T") || parseInt(cap) >= 500;
      if (filters.cap === "mid") return !cap.includes("T") && parseInt(cap) >= 50 && parseInt(cap) < 500;
      return !cap.includes("T") && parseInt(cap) < 50;
    });
    return list;
  }, [filters]);

  const stats = useMemo(() => {
    const values = Object.values(stocks);
    const total = values.length;
    const gainers = values.filter(x => x.change > 0).length;
    const losers = values.filter(x => x.change < 0).length;
    const avgVol = total ? Math.round(values.reduce((a,x)=>a+(x.volume||0),0)/total/1000000) : 0;
    return { total, gainers, losers, avgVol };
  }, [stocks]);

  const exportData = () => {
    const rows = [["Company","Symbol","Sector","Price","Change","%Change","Volume","Market Cap","P/E","CEO"]];
    Object.entries(companies).forEach(([name,company]) => {
      const d=stocks[name]; if (!d) return;
      rows.push([name,company.symbol,company.sector,d.price.toFixed(2),d.change.toFixed(2),d.changePercent,d.volume||0,company.marketCap,company.pe,company.ceo]);
    });
    const csv = rows.map(r => r.map(v => `"${String(v).replaceAll('"','""')}"`).join(",")).join("\n");
    const url=URL.createObjectURL(new Blob([csv],{type:"text/csv"}));
    const a=document.createElement("a"); a.href=url; a.download=`techstock-data-${new Date().toISOString().split("T")[0]}.csv`; a.click(); URL.revokeObjectURL(url);
  };

  return <div className="dashboard">
    <nav className="topbar"><div className="nav-content">
      <div className="brand"><i className="fas fa-chart-line brand-icon"/><span className="brand-text">TechStock</span><span className="brand-accent">PRO</span></div>
      <div className="nav-controls"><div className="market-status"><div className="status-dot active"/><span>{marketStatus}</span></div>
        <button className="btn-icon" onClick={()=>{const t=theme==="dark"?"light":"dark";setTheme(t);localStorage.setItem("theme",t)}}><i className={`fas ${theme==="light"?"fa-moon":"fa-palette"}`}/></button>
      </div>
    </div></nav>

    <div className="market-strip"><div className="market-ticker">{marketIndices.map(i=><div className="ticker-item" key={i.name}><span className="ticker-name">{i.name}</span><span className="ticker-price">${i.value.toLocaleString()}</span><span className={`ticker-change ${i.change>=0?"positive":"negative"}`}>{i.change>=0?"▲":"▼"} {Math.abs(i.change)}</span></div>)}</div></div>

    <div className="main-grid">
      <aside className="sidebar">
        <div className="panel watchlist-panel"><div className="panel-header"><h3><i className="fas fa-star"/> Watchlist</h3><span className="value-badge">${watchlist.reduce((s,n)=>s+(stocks[n]?.price||0),0).toLocaleString(undefined,{maximumFractionDigits:0})}</span></div>
          <div className="panel-body"><div className="watchlist-items">{watchlist.length===0?<div className="empty-state"><i className="fas fa-star"/><p>Your watchlist is empty</p></div>:watchlist.map(name=>{const d=stocks[name],c=companies[name];return <div className="watchlist-item" key={name} onClick={()=>setSelectedStock(name)}><div className="stock-info"><h4>{name}</h4><div className="stock-meta">{c.symbol} • {c.sector}</div></div><div className="stock-data"><div className="stock-price">${d.price.toFixed(2)}</div><div className={`stock-change ${d.change>=0?"positive":"negative"}`}>{d.change>=0?"+":""}{d.change.toFixed(2)}</div></div><button className="btn-remove" onClick={e=>{e.stopPropagation();removeFromWatchlist(name)}}><i className="fas fa-times"/></button></div>})}</div></div>
        </div>

        <div className="panel search-panel"><div className="panel-header"><h3><i className="fas fa-search"/> Search</h3></div><div className="panel-body">
          <div className="search-container"><input value={filters.search} onChange={e=>setFilters(f=>({...f,search:e.target.value}))} placeholder="Search stocks..." className="search-input"/><i className="fas fa-search search-icon"/></div>
          <div className="filters"><select value={filters.sector} onChange={e=>setFilters(f=>({...f,sector:e.target.value}))} className="filter-select"><option value="">All Sectors</option>{["Technology","Healthcare","Finance","Consumer","Energy"].map(x=><option key={x}>{x}</option>)}</select>
          <select value={filters.cap} onChange={e=>setFilters(f=>({...f,cap:e.target.value}))} className="filter-select"><option value="">All Cap</option><option value="large">Large Cap</option><option value="mid">Mid Cap</option><option value="small">Small Cap</option></select></div>
        </div></div>

        <div className="panel stats-panel"><div className="panel-header"><h3><i className="fas fa-chart-pie"/> Stats</h3></div><div className="panel-body"><div className="stats-grid">
          <div className="stat-item"><div className="stat-value">{stats.total}</div><div className="stat-label">Total</div></div><div className="stat-item gain"><div className="stat-value">{stats.gainers}</div><div className="stat-label">Gainers</div></div><div className="stat-item loss"><div className="stat-value">{stats.losers}</div><div className="stat-label">Losers</div></div><div className="stat-item"><div className="stat-value">{stats.avgVol}M</div><div className="stat-label">Avg Vol</div></div>
        </div></div></div>
      </aside>

      <main className="main-content">
        <div className="controls-bar"><div className="chart-controls">{[["line","fa-chart-line"],["area","fa-chart-area"],["bar","fa-chart-bar"]].map(([type,icon])=><button key={type} className={`ctrl-btn ${chartType===type?"active":""}`} onClick={()=>setChartType(type)}><i className={`fas ${icon}`}/></button>)}</div>
          <div className="action-controls"><button className="btn-primary" onClick={refresh} disabled={updating}><i className="fas fa-sync-alt"/> <span>{updating?"Updating...":"Refresh"}</span></button><button className="btn-secondary" onClick={exportData}><i className="fas fa-download"/></button></div>
        </div>
        <div className="charts-grid">{watchlist.length===0?<div className="empty-state"><i className="fas fa-chart-line"/><p>Add stocks to see live charts</p></div>:watchlist.map(name=><StockChart key={`${name}-${chartType}`} name={name} data={stocks[name]} company={companies[name]} type={chartType}/>)}</div>

        <div className="panel table-panel"><div className="panel-header"><h3><i className="fas fa-list"/> Stock Listings</h3><span className="count-badge">{filteredStocks.length}</span></div><div className="panel-body"><div className="table-container"><table className="data-table"><thead><tr><th>Company</th><th>Price</th><th>Change</th><th>Volume</th><th>Cap</th><th>Action</th></tr></thead><tbody>{filteredStocks.map(([name,c])=>{const d=stocks[name],added=watchlist.includes(name);return <tr className="stock-row" key={name} onClick={()=>setSelectedStock(name)}><td><div className="company-name">{name}</div><div className="company-symbol">{c.symbol} • {c.sector}</div></td><td className="price-cell">${d.price.toFixed(2)}</td><td className={`change-cell ${d.change>=0?"positive":"negative"}`}>{d.change>=0?"+":""}{d.change.toFixed(2)}<br/><small>({d.changePercent})</small></td><td className="volume-cell">{((d.volume||0)/1000000).toFixed(1)}M</td><td>{c.marketCap}</td><td><button className="btn-add" disabled={added} onClick={e=>{e.stopPropagation();if(!added)addToWatchlist(name)}}><i className={`fas ${added?"fa-check":"fa-plus"}`}/> {added?"Added":"Add"}</button></td></tr>})}</tbody></table></div></div></div>
      </main>
    </div>
    {selectedStock && <StockModal name={selectedStock} data={stocks[selectedStock]} company={companies[selectedStock]} inWatchlist={watchlist.includes(selectedStock)} onClose={()=>setSelectedStock(null)} onAdd={addToWatchlist} onRemove={removeFromWatchlist}/>}
    {loading && <div className="loading-screen"><div className="loader"><div className="loader-inner"/></div><p>Initializing Terminal...</p></div>}
  </div>;
}

function StockChart({name,data,company,type}) {
  const ref=useRef(null);
  useEffect(()=>{ if(!ref.current||!data)return; const ctx=ref.current.getContext("2d"); const color=data.change>=0?"#10b981":"#ef4444"; let gradient=null;if(type==="area"){gradient=ctx.createLinearGradient(0,0,0,250);gradient.addColorStop(0,color+"40");gradient.addColorStop(1,color+"00");}
    const chart=new Chart(ctx,{type:type==="area"?"line":type,data:{labels:data.history.slice(-20).map(h=>h.time),datasets:[{label:`${name} ($)`,data:data.history.slice(-20).map(h=>h.price),borderColor:color,backgroundColor:type==="area"?gradient:type==="bar"?color+"80":color+"20",borderWidth:type==="bar"?0:2,fill:type==="area",tension:type==="line"||type==="area"?0.4:0,pointRadius:type==="bar"?0:1,pointHoverRadius:type==="bar"?0:4}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{mode:"index",intersect:false}},scales:{x:{grid:{color:"#2d3748"},ticks:{color:"#6b7280",font:{family:"JetBrains Mono",size:10}}},y:{beginAtZero:false,grid:{color:"#2d3748"},ticks:{color:"#6b7280",font:{family:"JetBrains Mono",size:10},callback:v=>"$"+Number(v).toFixed(0)}}}}});
    return ()=>chart.destroy();
  },[data,type,name]);
  return <div className="chart-card fade-in"><div className="chart-header"><div><h4 className="chart-title">{name}</h4><div className="chart-symbol">{company.symbol} • {company.sector}</div></div><div><div className="chart-price">${data.price.toFixed(2)}</div><div className={`chart-change ${data.change>=0?"positive":"negative"}`}>{data.change>=0?"+":""}{data.change.toFixed(2)} ({data.changePercent})</div></div></div><div className="chart-container"><canvas ref={ref}/></div></div>;
}

function StockModal({name,data,company,inWatchlist,onClose,onAdd,onRemove}) {
  return <div className="modal show" onClick={e=>{if(e.target===e.currentTarget)onClose()}}><div className="modal-content"><div className="modal-header"><h2>{name} ({company.symbol}) - Stock Details</h2><button className="modal-close" onClick={onClose}>&times;</button></div><div className="modal-body"><div className="stock-details-container"><div className="price-overview"><div className="current-price"><h2>${data.price.toFixed(2)}</h2><div className={`price-change ${data.change>=0?"positive":"negative"}`}>{data.change>=0?"▲":"▼"} {data.change>=0?"+":""}{data.change.toFixed(2)} ({data.changePercent})</div></div></div>
  <div className="details-grid"><div className="chart-section"><h3><i className="fas fa-chart-line"/> Price Chart</h3><div className="modal-chart-container"><ModalChart name={name} data={data}/></div></div>
  <div className="info-section"><div className="metrics-grid"><Metric label="Volume" value={(data.volume||0).toLocaleString()}/><Metric label="Market Cap" value={company.marketCap}/><Metric label="P/E Ratio" value={company.pe}/><Metric label="Sector" value={company.sector}/></div>
  <div className="company-info"><h3><i className="fas fa-building"/> Company Information</h3><div className="info-grid"><Info label="CEO:" value={company.ceo}/><Info label="Founded:" value={company.founded}/><Info label="Employees:" value={company.employees}/><Info label="Last Updated:" value={new Date(data.lastUpdated).toLocaleTimeString()}/></div><div className="company-description"><h4>About {name}</h4><p>{company.description}</p></div></div>
  <div className="modal-actions"><button className={`btn-action ${inWatchlist?"btn-remove-modal":""}`} onClick={()=>{inWatchlist?onRemove(name):onAdd(name);onClose()}}><i className={`fas ${inWatchlist?"fa-star":"fa-plus"}`}/> {inWatchlist?"Remove from Watchlist":"Add to Watchlist"}</button></div></div></div></div></div></div></div>;
}
const Metric=({label,value})=><div className="metric-card"><div className="metric-label">{label}</div><div className="metric-value">{value}</div></div>;
const Info=({label,value})=><div className="info-row"><span className="info-label">{label}</span><span className="info-value">{value}</span></div>;

function ModalChart({name,data}) {
  const ref=useRef(null);
  useEffect(()=>{if(!ref.current)return;const ctx=ref.current.getContext("2d");const color=data.change>=0?"#10b981":"#ef4444";const gradient=ctx.createLinearGradient(0,0,0,250);gradient.addColorStop(0,color+"40");gradient.addColorStop(1,color+"00");
    const chart=new Chart(ctx,{type:"line",data:{labels:data.history.map(h=>h.time),datasets:[{label:`${name} Price`,data:data.history.map(h=>h.price),borderColor:color,backgroundColor:gradient,borderWidth:3,fill:true,tension:.4,pointRadius:2,pointHoverRadius:8,pointBackgroundColor:color,pointBorderColor:"#fff",pointBorderWidth:2}]},options:{responsive:true,maintainAspectRatio:false,interaction:{intersect:false,mode:"index"},plugins:{legend:{display:false},tooltip:{backgroundColor:"rgba(26,31,53,.95)",borderColor:color,borderWidth:2,displayColors:false,padding:12,callbacks:{title:c=>`${name} - ${c[0].label}`,label:c=>`Price: $${c.parsed.y.toFixed(2)}`,afterLabel:c=>{const h=data.history[c.dataIndex];return h?.volume?`Volume: ${(h.volume/1000000).toFixed(1)}M`:"";}}}},scales:{x:{grid:{color:"#2d3748"},ticks:{color:"#6b7280",font:{family:"JetBrains Mono",size:10}}},y:{beginAtZero:false,grid:{color:"#2d3748"},ticks:{color:"#6b7280",font:{family:"JetBrains Mono",size:10},callback:v=>"$"+Number(v).toFixed(0)}}}}});return()=>chart.destroy()},[data,name]);
  return <canvas ref={ref}/>;
}
export default App;
